// One item per brand. Listed here rather than fetched so a brand can be
// paused for a week by editing one line, without a deploy.
//
// Arak only for now: the other two workspaces have no verified Instagram
// handles, so a run would measure nothing and spend money saying so.
//
// CADENCE. Two lenses — rivals and craft — are deliberately monthly, because
// their answers move quarterly and asking every Monday buys the same answer
// four times. "Monthly" has to actually happen somewhere, though, or demoting
// a lens silently means deleting it. This trigger is the only thing that runs,
// so the first Monday of each month runs the monthly set (which is a superset
// of the weekly one) and every other Monday runs the weekly set.
const now = new Date();
const cadence = now.getDate() <= 7 ? 'monthly' : 'weekly';

return [
  {
    json: {
      workspace_id: '00000000-0000-0000-0000-000000000001',
      name: 'Arak Lighting',
      cadence,
    },
  },
];

// The route tells us which lenses this run wants. Read from the response
// rather than hardcoded here, so adding a lens is a code change in the repo
// — which is tested — and not an edit in this UI, which is not.
//
// The cadence comes back from the route too, and is carried onto every lens
// call. The lens route REFUSES a lens the run does not include, so a monthly
// run whose lens calls quietly defaulted to weekly would be rejected one lens
// at a time — and the failure would read as "this run does not include a
// rivals lens" rather than as the plumbing mistake it is.
const out = [];
for (const item of $input.all()) {
  const runId = item.json.run_id;
  const ws = item.json.workspace_id || $('Which brands').first().json.workspace_id;
  const cadence = item.json.cadence || $('Which brands').first().json.cadence || 'weekly';
  for (const lens of (item.json.next?.lenses || [])) {
    out.push({ json: { workspace_id: ws, run_id: runId, lens, cadence } });
  }
}
return out;

// The line a person reads if they check on this. Deliberately says when the
// CLOCK was the limit rather than the market — a run that quietly lost two
// lenses to a timeout looks exactly like a quiet week otherwise.
const r = $json;
const prev = $('Wait for every lens').first().json;
const bits = [
  r.ok ? 'Run complete.' : `Run did not complete: ${r.error || 'unknown'}`,
  r.headline ? `"${r.headline}"` : '',
  `${prev.lenses} lenses ran` + (prev.failed?.length ? `, ${prev.failed.length} failed (${prev.failed.join(', ')})` : ''),
  prev.timed_out?.length ? `${prev.timed_out.length} ran out of time (${prev.timed_out.join(', ')}) — a limit of the run, not a finding about the market` : '',
  r.proposed_ideas != null ? `${r.proposed_ideas} new ideas` : '',
  r.repeated_ideas ? `${r.repeated_ideas} dropped as repeats of earlier ones` : '',
  r.cost_usd != null ? `$${r.cost_usd}` : '',
].filter(Boolean);
return [{ json: { summary: bits.join(' · '), ...r } }];

// Runs once, after every lens item has come back. Emits a single item so
// synthesise is called once per run rather than once per lens.
//
// Deliberately NOT named for a number. The set is decided per run by sales
// motion and cadence — five on a weekly run, seven on a monthly one — and a
// node that assumed six would be wrong on both.
const items = $input.all();
const first = items[0]?.json || {};
const runId = first.run_id || $('One item per lens').first().json.run_id;
const ws = $('One item per lens').first().json.workspace_id;
const cadence = $('One item per lens').first().json.cadence || 'weekly';

const failed = items.filter(i => i.json?.lens_ok === false).map(i => i.json.lens);
const timedOut = items.filter(i => i.json?.timed_out).map(i => i.json.lens);

return [{ json: { workspace_id: ws, run_id: runId, cadence, lenses: items.length, failed, timed_out: timedOut } }];
